import { useCallback, useEffect, useMemo, useState } from 'react';
import { apiGet, apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import UnderlineHeading from '@/components/heading/UnderlineHeading';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { toast } from 'sonner';
import { useHasPermission } from '../hooks/usePermission';
import type { PaginatedPayload, RoleRow, StaffUserRow } from '../types/roles.types';
import { cn } from '@/lib/utils';

const UserRoleAssignmentPage = () => {
    const canList = useHasPermission('list_user');
    const canEdit = useHasPermission('edit_user');

    const [users, setUsers] = useState<StaffUserRow[]>([]);
    const [roles, setRoles] = useState<RoleRow[]>([]);
    const [page, setPage] = useState(1);
    const [lastPage, setLastPage] = useState(1);
    const [loadingUsers, setLoadingUsers] = useState(true);
    const [loadingRoles, setLoadingRoles] = useState(true);
    const [draftRoleId, setDraftRoleId] = useState<Record<number, string>>({});
    const [savingId, setSavingId] = useState<number | null>(null);

    const loadRoles = useCallback(async () => {
        setLoadingRoles(true);
        try {
            const res = await apiGet<{ data: PaginatedPayload<RoleRow> }>({
                endpoint: endpoints.accessControl.roleList,
                queryParams: { page: 1, pageSize: 200 },
            });
            const payload = res.data?.data;
            const rows = payload?.data ?? [];
            setRoles(rows.filter((r) => r.slug !== 'user'));
        } catch {
            setRoles([]);
            toast.error('تعذر تحميل قائمة الأدوار');
        } finally {
            setLoadingRoles(false);
        }
    }, []);

    const loadUsers = useCallback(async () => {
        setLoadingUsers(true);
        try {
            const res = await apiGet<{ data: PaginatedPayload<StaffUserRow> }>({
                endpoint: endpoints.admin.list,
                queryParams: { page, pageSize: 15 },
            });
            const payload = res.data?.data;
            const rows = payload?.data ?? [];
            setUsers(rows);
            setLastPage(payload?.pagination?.last_page ?? 1);
            setDraftRoleId((prev) => {
                const next = { ...prev };
                for (const u of rows) {
                    const first = u.roles?.[0]?.id;
                    next[u.id] = first != null ? String(first) : '';
                }
                return next;
            });
        } catch {
            setUsers([]);
            toast.error('تعذر تحميل المستخدمين');
        } finally {
            setLoadingUsers(false);
        }
    }, [page]);

    useEffect(() => {
        if (canList) {
            loadRoles();
        } else {
            setLoadingRoles(false);
        }
    }, [canList, loadRoles]);

    useEffect(() => {
        if (canList) {
            loadUsers();
        } else {
            setLoadingUsers(false);
        }
    }, [canList, loadUsers]);

    const handleSave = async (userId: number) => {
        const rid = draftRoleId[userId];
        if (!rid) {
            toast.error('اختر دوراً');
            return;
        }
        setSavingId(userId);
        try {
            await apiPost({
                endpoint: `${endpoints.accessControl.userAssignRole}${userId}`,
                body: { role_id: Number(rid) },
            });
            toast.success('تم تعيين الدور');
            await loadUsers();
        } catch (err: unknown) {
            const msg =
                err && typeof err === 'object' && 'response' in err
                    ? (err as { response?: { data?: { msg?: string } } }).response?.data?.msg
                    : null;
            toast.error(msg || 'فشل الحفظ');
        } finally {
            setSavingId(null);
        }
    };

    const isBusy = loadingUsers || loadingRoles;
    const colCount = canEdit ? 5 : 4;

    const roleOptions = useMemo(
        () =>
            roles.map((r) => (
                <option key={r.id} value={r.id}>
                    {r.name}
                </option>
            )),
        [roles],
    );

    if (!canList) {
        return <p className="mt-8 px-4 text-sm text-white-blue-700">ليس لديك صلاحية عرض المستخدمين.</p>;
    }

    return (
        <div className="mx-auto mt-6 w-full max-w-5xl px-4 pb-14">
            <UnderlineHeading text="تعيين الأدوار للمستخدمين" />
            <p className="mt-3 max-w-3xl text-sm leading-relaxed text-white-blue-700">
                ربط دور النظام (صلاحيات الدخول) بحسابات الموظفين والإداريين الذين لديهم تسجيل دخول. سجّل الموارد
                البشرية للموظفين بدون حساب منفصل في قسم الموارد البشرية.
            </p>

            <div
                className={cn(
                    'mt-8 overflow-hidden rounded-2xl border border-[#E4E2EC] bg-white shadow-[0_12px_40px_-12px_rgba(12,12,13,0.12)]',
                    isBusy && 'opacity-70 pointer-events-none',
                )}
            >
                <div className="overflow-x-auto">
                    <table className="w-full min-w-[640px] text-start text-sm">
                        <thead>
                            <tr className="border-b border-[#E4E2EC] bg-gradient-to-l from-primery-blue-500/8 to-transparent">
                                <th className="px-4 py-3.5 font-semibold text-primery-blue-600">المستخدم</th>
                                <th className="px-4 py-3.5 font-semibold text-primery-blue-600">البريد</th>
                                <th className="px-4 py-3.5 font-semibold text-primery-blue-600">الدور الحالي</th>
                                <th className="px-4 py-3.5 font-semibold text-primery-blue-600">تعيين</th>
                                {canEdit && <th className="px-4 py-3.5 font-semibold text-primery-blue-600 w-28"> </th>}
                            </tr>
                        </thead>
                        <tbody>
                            {users.length === 0 && !loadingUsers ? (
                                <tr>
                                    <td colSpan={colCount} className="px-4 py-10 text-center text-white-blue-700">
                                        لا يوجد مستخدمون مطابقون.
                                    </td>
                                </tr>
                            ) : (
                                users.map((u) => {
                                    const currentLabel = u.roles?.map((r) => r.name).join('، ') || '—';
                                    return (
                                        <tr key={u.id} className="border-b border-[#F0EEF5] last:border-0 hover:bg-primery-blue-500/[0.03]">
                                            <td className="px-4 py-3.5 font-medium text-white-blue-900">{u.name}</td>
                                            <td className="px-4 py-3.5 text-white-blue-700" dir="ltr">
                                                {u.email}
                                            </td>
                                            <td className="px-4 py-3.5">
                                                <span className="inline-flex rounded-full border border-primery-blue-100 bg-primery-blue-500/5 px-3 py-1 text-xs font-medium text-primery-blue-700">
                                                    {currentLabel}
                                                </span>
                                            </td>
                                            <td className="px-4 py-3.5 min-w-[200px]">
                                                <select
                                                    className="w-full rounded-lg border border-[#D8D6DE] bg-white px-3 py-2 text-sm text-white-blue-900 shadow-sm focus:border-primery-blue-400 focus:outline-none focus:ring-1 focus:ring-primery-blue-400"
                                                    value={draftRoleId[u.id] ?? ''}
                                                    disabled={!canEdit}
                                                    onChange={(e) =>
                                                        setDraftRoleId((prev) => ({
                                                            ...prev,
                                                            [u.id]: e.target.value,
                                                        }))
                                                    }
                                                >
                                                    <option value="">— اختر دوراً —</option>
                                                    {roleOptions}
                                                </select>
                                            </td>
                                            {canEdit && (
                                                <td className="px-4 py-3.5">
                                                    <PrimaryButton
                                                        type="button"
                                                        className="!px-3 !py-1.5 text-xs"
                                                        disabled={savingId === u.id || !draftRoleId[u.id]}
                                                        onClick={() => handleSave(u.id)}
                                                    >
                                                        {savingId === u.id ? '…' : 'حفظ'}
                                                    </PrimaryButton>
                                                </td>
                                            )}
                                        </tr>
                                    );
                                })
                            )}
                        </tbody>
                    </table>
                </div>
                {lastPage > 1 && (
                    <div className="flex items-center justify-between gap-4 border-t border-[#E4E2EC] bg-[#FAFAFC] px-4 py-3">
                        <span className="text-xs text-white-blue-700">
                            صفحة {page} من {lastPage}
                        </span>
                        <div className="flex gap-2">
                            <button
                                type="button"
                                className="rounded-lg border border-[#D8D6DE] bg-white px-3 py-1.5 text-xs font-medium text-primery-blue-600 disabled:opacity-40"
                                disabled={page <= 1}
                                onClick={() => setPage((p) => Math.max(1, p - 1))}
                            >
                                السابق
                            </button>
                            <button
                                type="button"
                                className="rounded-lg border border-[#D8D6DE] bg-white px-3 py-1.5 text-xs font-medium text-primery-blue-600 disabled:opacity-40"
                                disabled={page >= lastPage}
                                onClick={() => setPage((p) => p + 1)}
                            >
                                التالي
                            </button>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default UserRoleAssignmentPage;
